# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: sift
def sift(xs, factor=10):
    return [v * factor for v in xs[1:]]

# region: emit
def emit(xs, factor=10):
    return [v * factor for v in xs]

# region: intake
def intake(xs, offset=4):
    return [v + offset for v in xs]

# region: render
def render(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return fold(render(intake(emit(sift(digest(raw))))))

